//! part being head, chest, arms, waist, legs.
//!
//! The table layout was read out of the shipped GMD files:
//!   weaponNNMsgData_jpn.gmd[6 * weapon_id + 2 * form]
//!   armorSeriesData_jpn.gmd[10 * series + part]
//! form 0 is the base name and is what the save stores.

